package io.github.ningpp.compat;

import java.util.Map;
import java.util.WeakHashMap;

/**
 * Replacement for System.Runtime.CompilerServices.ConditionalWeakTable&lt;TKey, TValue&gt;
 * (generated by CSharpToJava converter).
 *
 * <p>The real .NET type associates a value with a key without keeping the key
 * alive. {@link WeakHashMap} gives the same reachability semantics, so it is used
 * as the backing store. All access is synchronized because the generated call
 * sites (collection deserialization) do not take an external lock.</p>
 *
 * @param <TKey> The type of the key.
 * @param <TValue> The type of the value.
 */
public final class ConditionalWeakTable<TKey, TValue> {

    private final Map<TKey, TValue> table = new WeakHashMap<>();

    public ConditionalWeakTable() {
    }

    /**
     * Adds a key/value pair if the key does not already exist.
     *
     * @param key The key to add.
     * @param value The value to associate with the key.
     */
    public synchronized void add(TKey key, TValue value) {
        if (key == null) {
            throw new ArgumentNullException("key");
        }
        if (value == null) {
            throw new ArgumentNullException("value");
        }
        if (table.containsKey(key)) {
            throw new ArgumentException("Key already exists.");
        }
        table.put(key, value);
    }

    /**
     * Removes a key and its value from the table.
     *
     * @param key The key to remove.
     * @return true if the key was found and removed.
     */
    public synchronized boolean remove(TKey key) {
        if (key == null) {
            throw new ArgumentNullException("key");
        }
        return table.remove(key) != null;
    }

    /**
     * Gets the value of the specified key.
     *
     * @param key The key whose value to retrieve.
     * @param value When this method returns, contains the value associated with
     *     the key, or the default value if the key was not found.
     * @return true if the key was found.
     */
    public synchronized boolean tryGetValue(TKey key, TValue value) {
        return tryGetValue(key, new ObjectHolder<TValue>(value));
    }

    /**
     * Gets the value of the specified key, storing it in {@code result.value}.
     * This overload mirrors the converter's ref/out parameter convention.
     *
     * @param key The key whose value to retrieve.
     * @param result Receives the value associated with the key.
     * @return true if the key was found.
     */
    public synchronized boolean tryGetValue(TKey key, ObjectHolder<TValue> result) {
        if (key == null) {
            throw new ArgumentNullException("key");
        }
        if (result == null) {
            throw new ArgumentNullException("result");
        }
        if (table.containsKey(key)) {
            result.value = table.get(key);
            return true;
        }
        result.value = null;
        return false;
    }

    /**
     * Gets the value of the specified key, adding it with the supplied callback
     * when the key is not present.
     *
     * @param key The key whose value to retrieve.
     * @param createValueCallback The factory used when the key is absent.
     * @return The existing or newly created value.
     */
    public synchronized TValue getValue(TKey key, java.util.function.Function<TKey, TValue> createValueCallback) {
        if (key == null) {
            throw new ArgumentNullException("key");
        }
        if (createValueCallback == null) {
            throw new ArgumentNullException("createValueCallback");
        }
        if (table.containsKey(key)) {
            return table.get(key);
        }
        TValue created = createValueCallback.apply(key);
        table.put(key, created);
        return created;
    }
}
